/**
 * Adds Mula's App Intents (Shortcuts actions) to the iOS app target.
 *
 * The Swift source lives in native/ios/ (ios/ is generated by prebuild and never committed).
 * Each intent writes a small JSON file into the app's Documents/intents folder; the app files
 * them into the inbox the next time it starts or comes to the foreground (see
 * src/modules/integrations/utils/intents.ts).
 */
const fs = require('fs');
const path = require('path');
const { IOSConfig, withDangerousMod, withXcodeProject } = require('expo/config-plugins');

const SOURCES = ['MulaIntents.swift'];

function withMulaIntents(config) {
  config = withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const { projectRoot, platformProjectRoot, projectName } = cfg.modRequest;
      const target = path.join(platformProjectRoot, projectName);
      fs.mkdirSync(target, { recursive: true });
      for (const file of SOURCES) {
        fs.copyFileSync(path.join(projectRoot, 'native', 'ios', file), path.join(target, file));
      }
      return cfg;
    },
  ]);

  config = withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const projectName = cfg.modRequest.projectName;
    const app = IOSConfig.XcodeUtils.getApplicationNativeTarget({ project, projectName });
    for (const file of SOURCES) {
      const filepath = `${projectName}/${file}`;
      if (project.hasFile(filepath)) continue;
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({ filepath, groupName: projectName, project, targetUuid: app.uuid });
    }
    return cfg;
  });

  return config;
}

module.exports = withMulaIntents;
